import {mkdir,readFile,writeFile,cp,lstat,readdir,readlink,realpath} from 'node:fs/promises';
import {join,dirname,relative} from 'node:path';import {spawnSync} from 'node:child_process';import assert from 'node:assert/strict';
const root=process.argv[1],scratch=process.argv[2],pkg=JSON.parse(await readFile(join(root,'kit/package.json'),'utf8'));
const snap=async(root)=>{const out={};const walk=async(p)=>{const s=await lstat(p,{bigint:true});out[relative(root,p)]={ino:String(s.ino),dev:String(s.dev),mode:String(s.mode),mtime:String(s.mtimeNs),ctime:String(s.ctimeNs),data:s.isSymbolicLink()?await readlink(p):s.isFile()?(await readFile(p)).toString('base64'):null};if(s.isDirectory())for(const n of(await readdir(p)).sort())await walk(join(p,n));};await walk(root);return JSON.stringify(out);};
const results={};
for(const [label,asset] of [['literal','.classifier-install.json'],['case-alias','.CLASSIFIER-INSTALL.JSON'],['normal',null]]){
 const source=join(scratch,label+'-package'),home=join(scratch,label+'-home');await mkdir(source);await mkdir(home);
 for(const p of [...pkg.files,'package.json','node_modules/@typesafe-ai/sdk']){const dst=join(source,p);await mkdir(dirname(dst),{recursive:true});await cp(join(root,'kit',p),dst,{recursive:true});}
 if(asset){await writeFile(join(source,asset),JSON.stringify({version:2,entries:[]}));await writeFile(join(source,'package.json'),JSON.stringify({...pkg,files:[...pkg.files,asset]}));}
 const env={PATH:process.env.PATH,HOME:home,TMPDIR:scratch};const run=(args,cwd=source)=>{const r=spawnSync(process.execPath,args,{cwd,env,encoding:'utf8',timeout:20000});return {exit:r.status,stdout:r.stdout,stderr:r.stderr};};
 const before=await snap(home);const installed=run([join(source,'bin/jev.mjs'),'install','cli','--apply','--dir',home,'--robot']);results[label]={install:installed};
 if(asset){assert.equal(installed.exit,64);assert.equal(await snap(home),before);results[label].wholeHomeUnchanged=true;if(label==='case-alias'){const a=await lstat(join(source,asset),{bigint:true});const b=await lstat(join(source,'.classifier-install.json'),{bigint:true});assert.equal(a.ino,b.ino);assert.equal(a.dev,b.dev);results[label].actualFilesystemAlias={dev:String(a.dev),ino:String(a.ino)};}}
 else{assert.equal(installed.exit,0);const bin=join(home,'.local/bin/classifier');results[label].version=run([bin,'--version']);assert.equal(results[label].version.stdout,`classifier ${pkg.version}\n`);const versionRoot=dirname(dirname(await realpath(bin)));results[label].sdk=run(['--input-type=module','--eval',"await import('@typesafe-ai/sdk'); console.log('SDK_ENTRY_LOADED')"],versionRoot);assert.equal(results[label].sdk.exit,0);assert.equal(results[label].sdk.stdout,'SDK_ENTRY_LOADED\n');const after=await snap(home);results[label].repeat=run([join(source,'bin/jev.mjs'),'install','cli','--apply','--dir',home,'--robot']);assert.equal(results[label].repeat.exit,0);assert.equal(JSON.parse(results[label].repeat.stdout).data.status,'already');assert.equal(await snap(home),after);results[label].wholeHomeRepeatUnchanged=true;}
}
console.log(JSON.stringify(results,null,2));

